parameters.jsCode:
const rows = $input.first().json.rows;
const projectId = rows[0].project_id;

const scenes = rows.map(row => ({
  scene_id: row.scene_id,
  scene_number: row.scene_number,
  title: row.scene_title,
  summary: row.summary,
  emotional_tone: row.emotional_tone,
  production_metadata: row.production_metadata || {},
  characters_present: JSON.parse(row.characters_present || '[]')
}));

return [{
  json: {
    project_id: projectId,
    title: rows[0].title,
    scenes: scenes,
    total_scenes: scenes.length
  }
}];

parameters.jsonBody:
={
  "model": "{{ $env.OLLAMA_MODEL || 'llama3' }}",
  "prompt": "You are an emotional cinematography director. Generate cinematography adjustments based on emotional data for each scene.

Project: '{{ $('Execute Logic').item.json.title }}'

Scenes: {{ JSON.stringify($('Execute Logic').item.json.scenes) }}

For each scene, generate:
1. lighting: {
     color_temperature: warm/cool/neutral,
     intensity: 1-10,
     direction: {front, side, back, overhead, under},
     shadows: soft/hard/dramatic/none,
     color_palette: array of hex colors
   }
2. camera: {
     lens_choice: {wide, normal, telephoto, macro},
     depth_of_field: shallow/medium/deep,
     angle_modifier: {level, slight-low, dramatic-low, slight-high, overhead},
     movement_energy: calm/moderate/intense
   }
3. transitions: {
     preferred_type: {cut, dissolve, fade, wipe},
     pacing: slow/moderate/fast,
     rhythm: steady/accelerating/decelerating
   }
4. color_grading: {
     mood: description,
     saturation: desaturated/normal/vibrant,
     contrast: low/medium/high
   }
5. emotional_arc_beats: array of {moment, intensity, visual_cue}

Return as JSON array with scene_id as key.",
  "stream": false,
  "format": "json"
}

parameters.jsCode:
const responseText = $input.first().json.response || '{}';
let emotionData = [];

try {
  const jsonMatch = responseText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    emotionData = JSON.parse(jsonMatch[0]);
  } else {
    const objMatch = responseText.match(/\{[\s\S]*\}/);
    if (objMatch) {
      const parsed = JSON.parse(objMatch[0]);
      emotionData = Object.entries(parsed).map(([key, val]) => ({ scene_id: key, ...val }));
    }
  }
} catch (e) {
  emotionData = [];
}

const projectId = $('Execute Logic').item.json.project_id;
const scenes = $('Execute Logic').item.json.scenes;

const sceneUpdates = emotionData.map(ed => {
  const scene = scenes.find(s => s.scene_id === ed.scene_id);
  return {
    json: {
      scene_id: ed.scene_id,
      project_id: projectId,
      emotion_cinematography: JSON.stringify({
        lighting: ed.lighting || {},
        camera: ed.camera || {},
        transitions: ed.transitions || {},
        color_grading: ed.color_grading || {},
        emotional_arc_beats: ed.emotional_arc_beats || []
      })
    }
  };
}).filter(s => s.json.scene_id);

return [{
  json: {
    project_id: projectId,
    scene_updates: sceneUpdates,
    total_adjusted: sceneUpdates.length
  }
}];

